
/*
    PROJETO GERENCIADOR DE TAREFAS

        Funcionalidades:
            - Cadastrar tarefas
                - Listar tarefas
                    - Buscar tarefas
                        - Concluir tarefas
                            - Alterar prioridades
                            */


                            // 1. Array de tarefas

                            let tarefas = [

                                {
                                        codigo: 1,
                                                titulo: "Estudar JavaScript",
                                                        prioridade: 1,
                                                                status: true
                                                                    },

                                                                        {
                                                                                codigo: 2,
                                                                                        titulo: "Fazer atividade de HTML",
                                                                                                prioridade: 2,
                                                                                                        status: false
                                                                                                            },

                                                                                                                {
                                                                                                                        codigo: 3,
                                                                                                                                titulo: "Organizar materiais da aula",
                                                                                                                                        prioridade: 3,
                                                                                                                                                status: true
                                                                                                                                                    }

                                                                                                                                                    ];


                                                                                                                                                    // 2. Gerador automático de códigos

                                                                                                                                                    let proximoCodigo = 3;


                                                                                                                                                    // 3. Mapeamento dos elementos HTML

                                                                                                                                                    const formTarefa = document.getElementById("formTarefa");

                                                                                                                                                    const tituloInput = document.getElementById("titulo");

                                                                                                                                                    const prioridadeInput = document.getElementById("prioridade");

                                                                                                                                                    const listaTarefas = document.getElementById("listaTarefas");

                                                                                                                                                    const mensagem = document.getElementById("mensagem");

                                                                                                                                                    const totalTarefas = document.getElementById("totalTarefas");

                                                                                                                                                    const totalPendentes = document.getElementById("totalPendentes");

                                                                                                                                                    const totalConcluidas = document.getElementById("totalConcluidas");

                                                                                                                                                    const filtroStatus = document.getElementById("filtroStatus");


                                                                                                                                                    // 4. Função para validar os dados da tarefa

                                                                                                                                                    function validarDadosDaTarefa(titulo, prioridade) {

                                                                                                                                                        // Validação do título

                                                                                                                                                            if (typeof titulo !== "string" || titulo.trim().length < 5) {

                                                                                                                                                                    throw new Error(
                                                                                                                                                                                "O título deve possuir no mínimo 5 caracteres."
                                                                                                                                                                                        );

                                                                                                                                                                                            }

                                                                                                                                                                                                // Validação da prioridade

                                                                                                                                                                                                    if (
                                                                                                                                                                                                            !Number.isInteger(prioridade) ||
                                                                                                                                                                                                                    prioridade < 1 ||
                                                                                                                                                                                                                            prioridade > 3
                                                                                                                                                                                                                                ) {

                                                                                                                                                                                                                                        throw new Error(
                                                                                                                                                                                                                                                    "A prioridade deve estar entre 1 e 3."
                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                // 5. Função para cadastrar tarefa

                                                                                                                                                                                                                                                                function cadastrarTarefa(titulo, prioridade) {

                                                                                                                                                                                                                                                                    // Validação dos dados

                                                                                                                                                                                                                                                                        validarDadosDaTarefa(titulo, prioridade);

                                                                                                                                                                                                                                                                            // Incremento do código

                                                                                                                                                                                                                                                                                proximoCodigo++;

                                                                                                                                                                                                                                                                                    // Criação do objeto tarefa

                                                                                                                                                                                                                                                                                        const tarefa = {

                                                                                                                                                                                                                                                                                                codigo: proximoCodigo,

                                                                                                                                                                                                                                                                                                        titulo: titulo.trim(),

                                                                                                                                                                                                                                                                                                                prioridade: prioridade,

                                                                                                                                                                                                                                                                                                                        status: true

                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                // Adicionando tarefa ao array

                                                                                                                                                                                                                                                                                                                                    tarefas.push(tarefa);

                                                                                                                                                                                                                                                                                                                                        return tarefa;

                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                        // 6. Função para listar tarefas

                                                                                                                                                                                                                                                                                                                                        function listarTarefas() {

                                                                                                                                                                                                                                                                                                                                            return tarefas;

                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                            // 7. Função para buscar tarefa com find

                                                                                                                                                                                                                                                                                                                                            function buscarTarefa(codigo) {

                                                                                                                                                                                                                                                                                                                                                const tarefa = tarefas.find(function(item) {

                                                                                                                                                                                                                                                                                                                                                        return item.codigo === codigo;

                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                // Tratamento de tarefa não encontrada

                                                                                                                                                                                                                                                                                                                                                                    if (!tarefa) {

                                                                                                                                                                                                                                                                                                                                                                            throw new Error(
                                                                                                                                                                                                                                                                                                                                                                                        "Tarefa não encontrada."
                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                        return tarefa;

                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                        // 8. Função para concluir tarefa

                                                                                                                                                                                                                                                                                                                                                                                                        function concluirTarefa(codigo) {

                                                                                                                                                                                                                                                                                                                                                                                                            const tarefa = buscarTarefa(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                // Verificar se já está concluída

                                                                                                                                                                                                                                                                                                                                                                                                                    if (tarefa.status === false) {

                                                                                                                                                                                                                                                                                                                                                                                                                            throw new Error(
                                                                                                                                                                                                                                                                                                                                                                                                                                        "Esta tarefa já está concluída."
                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Alterar status

                                                                                                                                                                                                                                                                                                                                                                                                                                                            tarefa.status = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                return tarefa;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 9. Função para alterar prioridade

                                                                                                                                                                                                                                                                                                                                                                                                                                                                function alterarPrioridade(codigo, novaPrioridade) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const tarefa = buscarTarefa(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Reutilizando a função de validação

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            validarDadosDaTarefa(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tarefa.titulo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            novaPrioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Alterando prioridade

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tarefa.prioridade = novaPrioridade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return tarefa;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 10. Função para exibir mensagens

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function mostrarMensagem(texto, tipo) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mensagem.textContent = texto;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagem.className = tipo;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 11. Função para converter prioridade em texto

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function obterPrioridade(prioridade) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (prioridade === 1) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            texto: "Alta",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        classe: "prioridade-alta"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (prioridade === 2) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            texto: "Média",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        classe: "prioridade-media"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                texto: "Baixa",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        classe: "prioridade-baixa"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 12. Função para renderizar as tarefas

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function renderizarTarefas() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Limpar tabela

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listaTarefas.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Obter tarefas cadastradas

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let tarefasExibidas = listarTarefas();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Aplicar filtro

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (filtroStatus.value === "pendentes") {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tarefasExibidas = tarefasExibidas.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tarefa => tarefa.status === true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (filtroStatus.value === "concluidas") {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefasExibidas = tarefasExibidas.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tarefa => tarefa.status === false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Percorrer as tarefas

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefasExibidas.forEach(function(tarefa) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const linha = document.createElement("tr");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const prioridade = obterPrioridade(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tarefa.prioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const statusTexto = tarefa.status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? "Pendente"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : "Concluída";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const statusClasse = tarefa.status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? "status-pendente"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : "status-concluida";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            linha.innerHTML = `

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td>${tarefa.codigo}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <td>${tarefa.titulo}</td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span class="${prioridade.classe}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ${prioridade.texto}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span class="${statusClasse}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ${statusTexto}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tarefa.status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                class="btn-concluir"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onclick="executarConclusao(${tarefa.codigo})"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Concluir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button class="btn-desativado" disabled>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Concluída
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            class="btn-prioridade"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onclick="executarAlteracaoPrioridade(${tarefa.codigo})"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Prioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listaTarefas.appendChild(linha);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Atualizar indicadores

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atualizarResumo();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 13. Função para atualizar o resumo

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function atualizarResumo() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                totalTarefas.textContent = tarefas.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const pendentes = tarefas.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tarefa => tarefa.status === true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ).length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const concluidas = tarefas.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tarefa => tarefa.status === false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ).length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    totalPendentes.textContent = pendentes;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        totalConcluidas.textContent = concluidas;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 14. Função para executar a conclusão

